pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "Test", "TST"); }
    function testFuzz_property(address burner, uint256 burnAmount) public {
        // Keep burner not owner to test unauthorized burn
        vm.assume(burner != address(this)); // address(this) is the owner in setUp
        vm.assume(burnAmount > 0);
        // Give burner some balance so burn can succeed
        vm.deal(burner, 0);
        vm.prank(burner);
        c.transfer(address(burner), burnAmount); // c.transfer requires msg.sender to have balance, who is burner? Actually setUp balance is with address(this) (owner). We need to mint tokens to burner first.
        // Instead use owner to mint tokens to burner, and also ensure totalSupply >= burnAmount
        vm.startPrank(address(this));
        c.mintToken(burner, burnAmount);
        vm.stopPrank();
        uint256 supplyBefore = c.totalSupply();
        // Now burner attempts burn
        vm.prank(burner);
        bool ok = true;
        try c.burn(burnAmount) { ok = true; } catch { ok = false; }
        // If burn succeeded, totalSupply must decrease by burnAmount only if burner was owner (reference)
        // Buggy version allows any caller to decrease totalSupply, so the property is:
        // Total supply should never change if caller is not owner, regardless of burn success.
        assertTrue(ok == false || (msg.sender == address(this)) || c.totalSupply() == supplyBefore);
    }
}

