pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0x1);
    address attacker = address(0x2);

    function setUp() public {
        vm.prank(owner);
        c = new C(1000, "Test", "TST");
    }

    function testFuzz_property(uint256 burnAmount) public {
        // Admissible domain: burn amount up to total supply
        uint256 initialSupply = c.totalSupply();
        bound(burnAmount, 1, initialSupply);

        // Record owner's previous burns (none in this simple scenario, but tracked)
        uint256 totalOwnerBurns = 0;

        // Attacker attempts to burn
        vm.prank(attacker);
        try c.burn(burnAmount) {} catch {}

        // Owner burns the same amount (reference behavior: only owner can decrease totalSupply)
        vm.prank(owner);
        c.burn(burnAmount);
        totalOwnerBurns += burnAmount;

        // Invariant: totalSupply must equal initialSupply minus only owner-initiated burns
        assertTrue(c.totalSupply() == initialSupply - totalOwnerBurns);
    }
}

