pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(uint256 initialMint, uint256 burnAmount, uint8 mintRecipients, uint256 salt) public {
        // 1. restrict domain to avoid overflow and ensure owner is unchanged
        vm.assume(initialMint > 0);
        vm.assume(burnAmount > 0);
        vm.assume(burnAmount <= initialMint);
        // 2. setup: mint initialMint to owner via mintToken, then distribute to several addresses
        address owner = c.owner();
        vm.prank(owner);
        c.mintToken(owner, initialMint);
        // generate up to 5 recipient addresses from salt
        uint8 n = uint8((mintRecipients % 5) + 1);
        address[5] memory recipients;
        for (uint8 i = 0; i < n; i++) {
            recipients[i] = address(uint160(uint256(keccak256(abi.encode(salt, i)))));
        }
        // transfer some tokens to recipients so state is more diverse
        uint256 distributed = 0;
        uint256 perRecipient = initialMint / n;
        for (uint8 i = 0; i < n - 1; i++) {
            vm.prank(owner);
            c.transfer(recipients[i], perRecipient);
            distributed += perRecipient;
        }
        uint256 lastAmount = initialMint - distributed;
        if (lastAmount > 0 && n > 0) {
            vm.prank(owner);
            c.transfer(recipients[n-1], lastAmount);
        }
        // ensure owner still has enough balance for burn
        uint256 ownerBal = c.balanceOf(owner);
        if (burnAmount > ownerBal) {
            burnAmount = ownerBal;
        }
        vm.assume(burnAmount > 0);
        // 3. burn and check invariant
        vm.prank(owner);
        c.burn(burnAmount);
        // compute sum of all known balances
        uint256 sum = 0;
        sum += c.balanceOf(owner);
        for (uint8 i = 0; i < n; i++) {
            sum += c.balanceOf(recipients[i]);
        }
        assertTrue(sum == c.totalSupply(), "Invariant broken: sum of balances != totalSupply");
    }
}

