import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "T", "S"); }
    function testFuzz_property(address ownerCandidate) public {
        // The fuzzer provides a candidate owner address.
        // The rule: owned() must NOT revert when called by the current owner.
        // The mutant always reverts, so it breaks this rule for the true owner.

        // Determine the current owner.
        address currentOwner = c.owner();

        // If the fuzzed address is the current owner, the call should succeed.
        vm.assume(ownerCandidate == currentOwner);

        vm.prank(ownerCandidate);
        bool success;
        try c.owned() { success = true; } catch { success = false; }

        // The owner calling owned() must succeed (not revert) on the reference.
        // The mutant reverts for the owner because of `require(false)`.
        assertTrue(success);
    }
}

