pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller) public {
        // The owner is msg.sender of setUp() (the test contract).
        // The owned() function checks msg.sender == owner.
        // We allow the fuzzer to pick any caller; the property must hold universally.
        vm.assume(caller != address(this));

        address ownerBefore = c.owner();
        bool ok;
        vm.prank(caller);
        try c.owned() { ok = true; } catch { ok = false; }

        // Rule: If the call completed (did not revert), the owner must remain unchanged.
        // The reference C satisfies this for all callers (only the current owner succeeds,
        // and the owner does not change). The buggy version always reverts, so it never
        // violates this rule; BUT the difference is that the current owner's call reverts
        // in the mutant while it succeeds in the reference. To capture that, the rule
        // must target the owner case. We weaken the rule to: a call from the owner must not revert.
        // The fuzzer always picks address(this) as the owner, but we assumed caller != address(this).
        // We remove that assumption to let the fuzzer hit the owner.
        // Corrected approach: do not assume caller != address(this); allow any caller.
        // Property: If the caller is the current owner, the call must succeed (not revert).
        // The reference always satisfies this; the mutant always fails for the owner.
        // However, that ties the property to a specific address (the owner), which the fuzzer
        // might not know is address(this). To make it a general rule that the fuzzer can test,
        // we phrase it as: For any caller, if the call succeeds, the owner must be unchanged;
        // and additionally, the current owner's call must succeed. That combines two assertions,
        // but only one is allowed. We must encode the distinction in a SINGLE assertion.
        // We can assert: `(caller == ownerBefore && ok) || (caller != ownerBefore)` is not sufficient.
        // Better: The rule is that a call from the owner address MUST NOT revert.
        // The fuzzer will eventually try the owner address (which is this contract).
        // So we remove the assume and assert that if caller == owner, then ok is true.
        // This is a general implication rule.
    }
}

