import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant OWNER = address(0x1234);

    function setUp() public {
        vm.prank(OWNER);
        c = new C(0, "", "");
    }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0) && caller != OWNER);

        // Make caller the owner by having the current owner call owned() to change ownership
        vm.prank(OWNER);
        c.transferOwnership(caller);

        // Now caller is the owner; a non-zero address must be able to call owned() successfully
        bool ok;
        vm.prank(caller);
        try c.owned() { ok = true; } catch { ok = false; }

        assertTrue(ok);
    }
}

